        function processText() {
            const mainInput = document.getElementById('source-text').value;

            // Pegar valores dos filtros
            const f1 = document.getElementById('filter1').value.trim();
            const f2 = document.getElementById('filter2').value.trim();
            const f3 = document.getElementById('filter3').value.trim();
            const f4 = document.getElementById('filter4').value.trim();
            const f5 = document.getElementById('filter5').value.trim();

            // Se todos estiverem vazios, não faz nada
            if (!f1 && !f2 && !f3 && !f4 && !f5) {
                alert("Por favor, insira pelo menos algo na caixa de filtro!");
                return;
            }

            // Escapar caracteres especiais para Regex (para funcionar com textos literais, ex: asteriscos não viram operadores matemáticos)
            const escapeRegExp = (string) => {
                return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); 
            };

            // Criar uma string combinada com OR (ou) para substituir tudo de uma vez
            // Usamos agrupamento não capturativo (?:(...) ) para lidar melhor com múltiplos padrões
