            patterns.push(escapeRegExp(f2));
            patterns.push(escapeRegExp(f3));
            patterns.push(escapeRegExp(f4));
            patterns.push(escapeRegExp(f5));

            const combinedPattern = "(?:" + patterns.join("|") + ")";

            // Executar substituição usando RegEx com flag 'g' (global) e 'm' (multiline)
            const finalText = mainInput.replace(new RegExp(combinedPattern, 'gm'), '');

            // Mostrar resultado
